    `<figure class='download-karte'><a href='${MOBILE_DOWNLOADS.notes.url}'>` +
    `<img class='download-qr' src='${MOBILE_DOWNLOADS.notes.qr}' alt='Magnolie Notes'>` +
    `<figcaption><b>Magnolie Notes</b><br>${MOBILE_DOWNLOADS.notes.filename}<br>gitlab.com</figcaption></a></figure>` +
    `<figure class='download-karte'><a href='${MOBILE_DOWNLOADS.kdeConnect.url}'>` +
    `<img class='download-qr' src='${MOBILE_DOWNLOADS.kdeConnect.qr}' alt='KDE Connect'>` +
    "<figcaption><b>KDE Connect</b><br>Google Play</figcaption></a></figure></div>";
